import{_ as t,o,c as r,a5 as i}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"SpringBoot 项目解决跨域的几种方案 1","description":"","frontmatter":{"title":"SpringBoot 项目解决跨域的几种方案 1","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/SpringBoot 项目解决跨域的几种方案 1.md","filePath":"posts/java快速入门/第十部分：常见需求/SpringBoot 项目解决跨域的几种方案 1.md"}'),s={name:"posts/java快速入门/第十部分：常见需求/SpringBoot 项目解决跨域的几种方案 1.md"};function l(n,e,a,p,u,c){return o(),r("div",null,[...e[0]||(e[0]=[i('<div><p>对于 CORS的跨域请求，主要有以下几种方式可供选择：</p><ul><li>返回新的CorsFilter</li><li>重写 WebMvcConfigurer</li><li>使用注解 @CrossOrigin</li><li>手动设置响应头 (HttpServletResponse)</li><li>自定web filter 实现跨域</li></ul><p>注意 CorFilter / WebMvConfigurer / @CrossOrigin 需要 SpringMVC 4.2以上版本才支持，对应springBoot 1.3版本以上</p><p>上面前两种方式属于全局 CORS 配置，后两种属于局部 CORS配置。如果使用了局部跨域是会覆盖全局跨域的规则，所以可以通过 @CrossOrigin 注解来进行细粒度更高的跨域资源控制。</p><p>其实无论哪种方案，最终目的都是修改响应头，向响应头中添加浏览器所要求的数据，进而实现跨域 1.返回新的 CorsFilter(全局跨域) 在任意配置类，返回一个 新的 CorsFIlter Bean ，并添加映射路径和具体的CORS配置路径。</p><p>@Configuration public class GlobalCorsConfig { @Bean public CorsFilter corsFilter() { //1. 添加 CORS配置信息 CorsConfiguration config = new CorsConfiguration(); //放行哪些原始域 config.addAllowedOrigin(&quot;<em>&quot;); //是否发送 Cookie config.setAllowCredentials(true); //放行哪些请求方式 config.addAllowedMethod(&quot;</em>&quot;); //放行哪些原始请求头部信息 config.addAllowedHeader(&quot;<em>&quot;); //暴露哪些头部信息 config.addExposedHeader(&quot;</em>&quot;); //2. 添加映射路径 UrlBasedCorsConfigurationSource corsConfigurationSource = new UrlBasedCorsConfigurationSource(); corsConfigurationSource.registerCorsConfiguration(&quot;/<strong>&quot;,config); //3. 返回新的CorsFilter return new CorsFilter(corsConfigurationSource); } } 2. 重写 WebMvcConfigurer(全局跨域) @Configuration public class CorsConfig implements WebMvcConfigurer { @Override public void addCorsMappings(CorsRegistry registry) { registry.addMapping(&quot;/</strong>&quot;) //是否发送Cookie .allowCredentials(true) //放行哪些原始域 .allowedOrigins(&quot;<em>&quot;) .allowedMethods(new String[]{&quot;GET&quot;, &quot;POST&quot;, &quot;PUT&quot;, &quot;DELETE&quot;}) .allowedHeaders(&quot;</em>&quot;) .exposedHeaders(&quot;*&quot;); } } ￼3.使用注解 (局部跨域) 在控制器(类上)上使用注解 @CrossOrigin:，表示该类的所有方法允许跨域。</p><p>@RestController @CrossOrigin(origins = &quot;*&quot;) public class HelloController { @RequestMapping(&quot;/hello&quot;) public String hello() { return &quot;hello world&quot;; } } ￼在方法上使用注解 @CrossOrigin:</p><p>@RequestMapping(&quot;/hello&quot;) @CrossOrigin(origins = &quot;*&quot;) //@CrossOrigin(value = &quot;<a href="http://localhost:8081" target="_blank" rel="noreferrer">http://localhost:8081</a>&quot;) //指定具体ip允许跨域 public String hello() { return &quot;hello world&quot;; }</p><ol start="4"><li>手动设置响应头(局部跨域) 使用 HttpServletResponse 对象添加响应头(Access-Control-Allow-Origin)来授权原始域，这里 Origin的值也可以设置为 “*”,表示全部放行。</li></ol><p>@RequestMapping(&quot;/index&quot;) public String index(HttpServletResponse response) { response.addHeader(&quot;Access-Allow-Control-Origin&quot;,&quot;*&quot;); return &quot;index&quot;; } ￼5. 使用自定义filter实现跨域 ssm种的写法 首先编写一个过滤器，可以起名字为MyCorsFilter.java</p><p>package com.mesnac.aop;</p><p>import java.io.IOException; import javax.servlet.Filter; import javax.servlet.FilterChain; import javax.servlet.FilterConfig; import javax.servlet.ServletException; import javax.servlet.ServletRequest; import javax.servlet.ServletResponse; import javax.servlet.http.HttpServletResponse; import org.springframework.stereotype.Component; @Component public class MyCorsFilter implements Filter { public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) throws IOException, ServletException { HttpServletResponse response = (HttpServletResponse) res; response.setHeader(&quot;Access-Control-Allow-Origin&quot;, &quot;*&quot;); response.setHeader(&quot;Access-Control-Allow-Methods&quot;, &quot;POST, GET, OPTIONS, DELETE&quot;); response.setHeader(&quot;Access-Control-Max-Age&quot;, &quot;3600&quot;); response.setHeader(&quot;Access-Control-Allow-Headers&quot;, &quot;x-requested-with,content-type&quot;); chain.doFilter(req, res); } public void init(FilterConfig filterConfig) {} public void destroy() {} } 在web.xml中配置这个过滤器，使其生效</p><p>&lt;!-- 跨域访问 START--&gt; &lt;filter&gt; &lt;filter-name&gt;CorsFilter&lt;/filter-name&gt; &lt;filter-class&gt;com.mesnac.aop.MyCorsFilter&lt;/filter-class&gt; &lt;/filter&gt; &lt;filter-mapping&gt; &lt;filter-name&gt;CorsFilter&lt;/filter-name&gt; &lt;url-pattern&gt;/*&lt;/url-pattern&gt; &lt;/filter-mapping&gt; &lt;!-- 跨域访问 END --&gt;</p><p>springboot可以简化 import org.springframework.context.annotation.Configuration; import javax.servlet.<em>; import javax.servlet.annotation.WebFilter; import javax.servlet.http.HttpServletResponse; import java.io.IOException; @WebFilter(filterName = &quot;CorsFilter &quot;) @Configuration public class CorsFilter implements Filter { @Override public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) throws IOException, ServletException { HttpServletResponse response = (HttpServletResponse) res; response.setHeader(&quot;Access-Control-Allow-Origin&quot;,&quot;</em>&quot;); response.setHeader(&quot;Access-Control-Allow-Credentials&quot;, &quot;true&quot;); response.setHeader(&quot;Access-Control-Allow-Methods&quot;, &quot;POST, GET, PATCH, DELETE, PUT&quot;); response.setHeader(&quot;Access-Control-Max-Age&quot;, &quot;3600&quot;); response.setHeader(&quot;Access-Control-Allow-Headers&quot;, &quot;Origin, X-Requested-With, Content-Type, Accept&quot;); chain.doFilter(req, res); } } ￼esponse.setHeader(“Access-Control-Max-Age”, “3600”); response.setHeader(“Access-Control-Allow-Headers”, “Origin, X-Requested-With, Content-Type, Accept”); chain.doFilter(req, res); } }</p></div>',1)])])}const C=t(s,[["render",l]]);export{g as __pageData,C as default};
